-- SQL Schema for notifier module
-- Generated by flow2code
-- Database: SQLite

-- Notification table schema
CREATE TABLE notifications (
    -- id: main ID
    id VARCHAR(64) PRIMARY KEY,
    -- id_user: User ID who should receive this notification
    id_user VARCHAR(64) NOT NULL,
    -- event_type: Event type that triggered this notification
    event_type VARCHAR(200) NOT NULL,
    -- title: Notification title
    title VARCHAR(200) NOT NULL,
    -- message: Notification message
    message VARCHAR(200) NOT NULL,
    -- status: Status: 'pending', 'dismissed', 'snoozed', 'shown'
    status VARCHAR(20) NOT NULL,
    -- snooze_until: Snooze until timestamp (null if not snoozed)
    snooze_until INTEGER,
    -- data: Additional data as JSON
    data VARCHAR(200),
    -- notification_type: Notification type for UI: 'info', 'success', 'warning', 'error'
    notification_type VARCHAR(20) NOT NULL,
    -- domain: Domain field for multi-tenancy
    domain VARCHAR(200) NOT NULL,
    -- created: Notification created date
    created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- updated: Notification updated date
    updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Index on created: Notification created date
CREATE INDEX idx_notifications_created ON notifications(created);

-- Index on updated: Notification updated date
CREATE INDEX idx_notifications_updated ON notifications(updated);


-- NotificationSetting table schema
CREATE TABLE notification_settings (
    -- id: main ID
    id VARCHAR(64) PRIMARY KEY,
    -- id_user: User ID
    id_user VARCHAR(64) NOT NULL,
    -- event_type: Event type to configure
    event_type VARCHAR(200) NOT NULL,
    -- enabled: Whether this event type is enabled for notifications
    enabled INTEGER NOT NULL,
    -- domain: Domain field for multi-tenancy
    domain VARCHAR(200) NOT NULL
);


